window.POLICY = window.POLICY || {};
window.POLICY["pol_member.html"] = {"title": "픽콕 리워드 회원 정책서 v0.2", "s": {"s0": {"t": "0. 결정 요약", "h": "<table>\n<thead>\n<tr>\n  <th>#</th>\n  <th>쟁점</th>\n  <th>결정</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>1</td>\n  <td>로그인 수단</td>\n  <td><strong>이메일 + 인증코드(비밀번호 없음)</strong> 하나로 가입과 로그인을 함께 처리</td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-1</td>\n</tr>\n<tr>\n  <td>2</td>\n  <td>가입 때 본인인증</td>\n  <td><strong>받지 않는다</strong> — 첫 적립 때 받는다. 단 <strong>가입 직후 한 번 권유 팝업</strong>(건너뛸 수 있음 · 1-2 ⑤)</td>\n  <td><code>[PO 확정 2026-10-26]</code> 참여형 1-6 · 권유 팝업 <code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>3</td>\n  <td>가입 직후 이름</td>\n  <td>이메일 앞부분을 임시 이름으로 · 본인인증하면 실명으로 바뀐다</td>\n  <td><code>[PO 확정 2026-10-27]</code> <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>4</td>\n  <td>탈퇴 시 포인트</td>\n  <td><strong>보유 포인트 + 적립대기 포인트 모두 소멸</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>5</td>\n  <td>재가입 제한</td>\n  <td><strong>탈퇴 후 7일간 같은 이메일로 가입 불가</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code> — 구현 화면 문구와 같음</td>\n</tr>\n<tr>\n  <td>6</td>\n  <td>간편 로그인</td>\n  <td><strong>카카오·네이버 — 시연용 흉내만</strong> (실연동 안 함). 버튼 위치와 분기 흐름을 보여주는 것이 목적</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>7</td>\n  <td>계정 연결·통합</td>\n  <td><strong>넣는다.</strong> 붙이려는 소셜이 이미 다른 회원 것이면 <strong>계정 통합</strong>, 아니면 <strong>계정 연결</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>8</td>\n  <td>중복 본인인증(CI)</td>\n  <td>같은 사람이 다른 계정에 이미 인증돼 있으면 <strong>지급하지 않고 계정 통합으로 잇는다</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>9</td>\n  <td>통합 시 포인트</td>\n  <td><strong>전액 합산 · 소멸일은 각 적립일 기준 그대로</strong> (재산정하지 않음)</td>\n  <td><code>[앱 정책]</code> 01-3 1-6-7</td>\n</tr>\n<tr>\n  <td><del>6</del></td>\n  <td><del>간편 가입·계정 통합</del></td>\n  <td><del>다음 단계</del> → <strong>v0.2에서 본문 편입</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s1": {"t": "1. 가입·로그인", "h": "<h2 id=\"s1-1\">1-1. 진입</h2>\n<ul>\n<li>진입 경로: 홈 상단 [로그인] · 마이페이지 [로그인] · 비로그인이 참여 버튼을 눌렀을 때 · <strong>초대 링크</strong>(<code>/signup?ref=코드</code>, 로그인 전이면 가입 시트가 바로 열림 — 참여형 4-9). <code>[구현]</code></li>\n<li>화면: 아래에서 올라오는 <strong>단계형 바텀시트</strong> 하나에서 가입·로그인을 함께 처리한다 (C-LAYER L-SHEET-STEP). <code>[구현]</code></li>\n</ul>\n<h2 id=\"s1-2\">1-2. 흐름</h2>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>화면 문구</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>① 이메일</td>\n  <td>「회원가입 / 로그인」 · &quot;이메일만 있으면 돼요. 비밀번호는 없어요.&quot;</td>\n  <td>이메일 형식이 맞아야 [인증코드 받기]가 켜진다. 누르면 「보내는 중…」</td>\n</tr>\n<tr>\n  <td>② 인증코드</td>\n  <td>「인증코드를 입력해 주세요」 · &quot;{이메일}로 6자리 코드를 보냈어요. 유효시간 5분&quot;</td>\n  <td>6자리 개별 칸 · <strong>6자리가 차면 자동 확인</strong> · 틀리면 칸을 비우고 빨간 글씨 &quot;인증코드가 일치하지 않아요. 다시 입력해 주세요.&quot; · [인증코드 다시 받기]</td>\n</tr>\n<tr>\n  <td>③-가 기존 회원</td>\n  <td>—</td>\n  <td>시트가 닫히고 즉시 로그인 · 토스트 &quot;로그인 완료 · 내 저금통이 열렸어요&quot; · <strong>보던 화면에 그대로 남는다</strong></td>\n</tr>\n<tr>\n  <td>③-나 신규 회원</td>\n  <td>「거의 다 됐어요」 · &quot;약관에 동의하면 가입이 끝나요.&quot;</td>\n  <td>약관 3종 + 친구 추천코드(선택) → [가입 완료] (1-3)</td>\n</tr>\n<tr>\n  <td>④ 가입 완료</td>\n  <td>「가입을 환영해요!」 · &quot;이제 포인트를 모을 수 있어요&quot;</td>\n  <td>약 1.7초 뒤 자동으로 닫히고 토스트 &quot;회원가입을 완료했어요 · 내 저금통이 열렸어요&quot;. 추천코드로 포인트를 받았으면 적립 연출을 먼저 보여준다 (참여형 4절)</td>\n</tr>\n<tr>\n  <td>⑤ 본인인증 권유 <em>(같은 날 추가 — 대화창4)</em></td>\n  <td>확인창 「본인인증을 해야 포인트 적립이 가능해요」 · &quot;지금 하지 않아도 돼요. 적립할 때 다시 안내해 드려요.&quot;</td>\n  <td>④가 닫힌 직후. <strong>[다음에 하기]</strong> → 닫고 보던 화면 그대로 · <strong>[본인인증하기]</strong> → 본인인증 시트(2-2). 인증을 마치면 적립대기를 지급하고 시트가 닫힌다 — 이어서 할 참여는 없다. <strong>띄우지 않는 경우:</strong> ①출석 카드 [로그인하고 출석하기] · 퀴즈 화면 [로그인하고 시작하기]로 가입했을 때 — 적립 버튼을 누르면 관문(2-1)에서 바로 묻기 때문(두 번 묻지 않음) ②기존 회원 로그인. 추천코드를 넣고 가입해도 <strong>문구는 같다</strong>(받을 금액을 보여주지 않음) <code>[PO 확정 2026-10-27]</code> <code>[구현]</code></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>가입·로그인 여부는 <strong>서버가 판단</strong>한다 — 이메일을 보내면 회원인지 알려 주고, 사용자는 고르지 않는다. <code>[구현]</code></li>\n<li>인증코드 유효시간 <strong>5분</strong>, 다시 받기 <strong>횟수 제한 없음</strong>. <code>[앱 정책]</code> — ⚠ 구현물은 발송·만료를 흉내만 낸다(시연용 — 아무 6자리 통과). 실제 발송·만료·시도 횟수 제한은 개발 대상</li>\n<li>시트 [✕]: ①단계면 &quot;닫을까요?&quot; · ②단계부터는 &quot;가입을 그만둘까요? — 지금 닫으면 입력한 내용이 사라지고 처음부터 다시 해야 해요.&quot; 확인창. <code>[구현]</code></li>\n<li>가입 인원 제한: 어드민 설정 <code>max_users</code>(0 = 제한 없음). 넘으면 가입 거절. <code>[구현]</code> — 시연용 장치, 상용 사용 여부 미정</li>\n</ul>\n<h2 id=\"s1-3\">1-3. 약관·추천코드 (신규 회원)</h2>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>약관</td>\n  <td>[필수] 서비스 이용약관 · [필수] 개인정보 수집·이용 · [선택] 마케팅 정보 수신 — 필수 2개를 체크해야 [가입 완료]가 켜진다 <code>[구현]</code> <code>[앱 정책]</code> 1-8</td>\n</tr>\n<tr>\n  <td>약관 [보기]</td>\n  <td>지금은 토스트로 위치만 안내(시연) → 개발 시 약관 전문 화면 <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>마케팅 동의</td>\n  <td>가입 때 고른 값이 계정의 마케팅 수신 설정이 된다 <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>친구 추천코드</td>\n  <td>접힌 칸 · 넣으면 [조회]를 마쳐야 가입 — 상세는 참여형 4-2절</td>\n</tr>\n<tr>\n  <td>회원 생성 시점</td>\n  <td><strong>[가입 완료]를 누른 순간</strong> — 약관 동의 전에는 계정을 만들지 않는다 <code>[구현]</code> <code>[앱 정책]</code> 1-8</td>\n</tr>\n<tr>\n  <td>가입 실패</td>\n  <td>서버 처리 실패 → 확인창 &quot;가입하지 못했어요&quot; + [다시 시도](가입 요청을 다시 보냄). 계정은 만들어졌는데 <strong>추천코드 적용만 실패</strong>하면 [다시 시도]는 코드만 다시 적용한다 — 계정을 또 만들지 않는다 (C-LAYER R3) <code>[구현]</code></td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"s1-4\">1-4. 세션</h2>\n<ul>\n<li>로그인 유지 <strong>30일</strong> (쿠키 만료 30일). <code>[구현]</code> — 앱 정책은 앱에서 <strong>무기한</strong>(1-11). 리워드 앱 출시 때 어느 쪽으로 할지 → 미결 R-M7</li>\n<li>로그인 직후 서버에서 잔액·본인인증 여부·적립대기 여부를 다시 받는다. <code>[구현]</code></li>\n</ul>\n<hr />\n<h2 id=\"s1-5\">1-5. 간편 로그인 — 카카오·네이버 <em>(v0.2 신설)</em></h2>\n<blockquote>\n<p><strong>실제로 연동하지 않는다.</strong> 버튼이 어디에 있고 누르면 어떤 흐름으로 가는지를 보여주기 위한 <strong>시연용 흉내</strong>다. <code>[PO 확정 2026-10-27]</code></p>\n</blockquote>\n<p><strong>왜 흉내로 두는가</strong> <code>[원문]</code> <code>03_조사/09_간편가입_본인인증_타사조사_v0.1.md</code></p>\n<table>\n<thead>\n<tr>\n  <th>사업자</th>\n  <th>실연동에 필요한 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>카카오</td>\n  <td>비즈 앱 전환 → 비즈니스 정보 심사 · 개인정보 동의항목 심사 <strong>영업일 3~5일</strong>. 전화번호·CI는 별도 권한</td>\n</tr>\n<tr>\n  <td>네이버</td>\n  <td>서비스 적용에 <strong>검수 승인</strong> 필요 · <strong>CI를 주지 않는다</strong> · 휴대전화번호는 동의 시 제공</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>결정적인 것은 <strong>카카오 CI 권한 조건</strong>이다 — <em>「서비스 회원가입에 본인확인 기관에 의한 본인 인증 기능이 확인된 경우만 설정 권한 제공」</em> <code>[2차]</code>.\n즉 <strong>PASS를 먼저 갖춰야 CI를 받는 구조</strong>라, 실연동해도 <strong>중복 인증 판정에 쓸 CI는 얻지 못한다.</strong> 중복 인증·계정 통합 검증이 목적이라면 실연동의 실익이 없다.</li>\n</ul>\n<p><strong>화면</strong></p>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>가입·로그인 바텀시트에서 <strong>이메일 입력 칸 아래</strong> · 구분선 「또는」 · <strong>카카오 · 네이버</strong> 버튼 2개를 가로로</td>\n</tr>\n<tr>\n  <td>표기</td>\n  <td>버튼 아래 안내 한 줄 — <strong>「시연용이에요. 실제 카카오·네이버 로그인은 연결되어 있지 않아요.」</strong></td>\n</tr>\n<tr>\n  <td>누르면</td>\n  <td>「연결 중…」을 약 1초 보여준 뒤 <strong>그 소셜의 로그인 화면을 흉내 낸 단계</strong>가 뜬다 — <strong>이메일(아이디)을 직접 입력</strong>한다 <code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>왜 직접 넣게 하나</td>\n  <td>소셜마다 결과를 고정해 두면 시연 중에 바꿀 수 없다. <strong>입력한 이메일에 따라 갈라지게</strong> 하면 연결·통합·신규가입 <strong>세 결과를 그 자리에서 보여줄 수 있다</strong></td>\n</tr>\n<tr>\n  <td>입력 화면 안내</td>\n  <td>「시연용 화면이에요. 실제 OO 로그인 창이 아니에요.」 + <strong>어떤 주소를 넣으면 어떤 결과가 나오는지</strong> 한 줄 안내</td>\n</tr>\n<tr>\n  <td>고른 뒤</td>\n  <td>고른 소셜로 로그인한 것으로 처리하고 <strong>아래 분기</strong>를 탄다</td>\n</tr>\n</tbody>\n</table>\n<p><strong>분기 — 버튼은 하나, 결과는 두 가지</strong> <code>[앱 정책]</code> 01-3 1-6-4</p>\n<pre><code>[카카오로 시작하기] 탭\n      │\n      ▼ 「카카오 인증 중…」 (약 1초)\n      │\n      ▼ 카카오 로그인 화면(흉내) — 이메일(아이디) 입력\n      │\n      ▼ 넣은 이메일로 판단\n      ├─ 픽콕의 **다른 회원**        → 계정 통합 (3-2)  &quot;두 계정을 합칠까요?&quot;\n      ├─ **내 계정**과 같다(로그인 중) → 계정 연결 (3-1)  &quot;카카오가 연결됐어요&quot;\n      ├─ **이미 가입된 주소**(로그인 전) → 그 계정으로 **로그인 + 소셜 자동 연결**\n      └─ 픽콕에 **없다**             → 로그인 중이면 연결 · 아니면 **신규 가입**(약관 → 완료)\n</code></pre>\n<table>\n<thead>\n<tr>\n  <th>넣은 이메일</th>\n  <th>결과</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>픽콕의 다른 회원 (로그인 중)</td>\n  <td><strong>계정 통합 확인</strong>(3-2) — 합쳐질 계정·포인트 합계를 보여준다</td>\n  <td>01-3 1-6-2</td>\n</tr>\n<tr>\n  <td>내 계정과 같음 (로그인 중)</td>\n  <td><strong>계정 연결</strong>(3-1) · 토스트 「OO가 연결됐어요」</td>\n  <td>01-3 1-6-6</td>\n</tr>\n<tr>\n  <td>이미 가입된 주소 (로그인 전)</td>\n  <td><strong>그 계정으로 로그인 + 그 소셜을 로그인 수단으로 자동 연결</strong> — 합칠 상대가 없으므로 통합이 아니다</td>\n  <td><code>[PO 확정 2026-10-27]</code> · 01-3 1-4</td>\n</tr>\n<tr>\n  <td>픽콕에 없음</td>\n  <td>로그인 중 → <strong>연결</strong> / 로그인 전 → <strong>신규 가입</strong></td>\n  <td>01-3 1-6-1</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>사용자는 누르기 전에 결과를 알 수 없다. <strong>고른 뒤에 시스템이 판단해 나눈다.</strong></li>\n<li>신규 가입으로 들어와도 <strong>본인인증은 첫 적립 때</strong> 받는다(2-1). 간편 로그인이라고 달라지지 않는다.</li>\n<li><strong>판단은 서버가 한다</strong> <em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code> — 넣은 이메일을 서버가 찾는다(대표 이메일 → 없으면 통합 때 남긴 옛 이메일). 로그인 전에 가입된 주소면 <strong>서버에 로그인까지</strong> 한다(전: 화면만 로그인 → 새로고침·적립 때 「로그인이 필요해요」 · K19). 로그인 전에는 다른 회원 이메일도 「이미 가입된 주소」 줄 — 그 계정으로 로그인한다(K21). 통합은 로그인 중일 때만.</li>\n<li>시연 더미 <code>old.pickoq@naver.com</code>은 서버에 없는 통합 시연용 주소다 — 로그인 전에 넣으면 토스트 「통합 시연용 주소예요. 로그인한 뒤 계정관리 [연결]에서 넣어 주세요」 <em>(10-28 회원 묶음 — 대화창4)</em></li>\n<li>소셜로 <strong>신규 가입</strong>하면 그 소셜이 연결되고 「현재 로그인」 수단이 된다(K20) <em>(10-28 회원 묶음 — 대화창4)</em></li>\n</ul>\n<hr />"}, "s1-1": {"t": "1-1. 진입", "h": "<ul>\n<li>진입 경로: 홈 상단 [로그인] · 마이페이지 [로그인] · 비로그인이 참여 버튼을 눌렀을 때 · <strong>초대 링크</strong>(<code>/signup?ref=코드</code>, 로그인 전이면 가입 시트가 바로 열림 — 참여형 4-9). <code>[구현]</code></li>\n<li>화면: 아래에서 올라오는 <strong>단계형 바텀시트</strong> 하나에서 가입·로그인을 함께 처리한다 (C-LAYER L-SHEET-STEP). <code>[구현]</code></li>\n</ul>"}, "s1-2": {"t": "1-2. 흐름", "h": "<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>화면 문구</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>① 이메일</td>\n  <td>「회원가입 / 로그인」 · &quot;이메일만 있으면 돼요. 비밀번호는 없어요.&quot;</td>\n  <td>이메일 형식이 맞아야 [인증코드 받기]가 켜진다. 누르면 「보내는 중…」</td>\n</tr>\n<tr>\n  <td>② 인증코드</td>\n  <td>「인증코드를 입력해 주세요」 · &quot;{이메일}로 6자리 코드를 보냈어요. 유효시간 5분&quot;</td>\n  <td>6자리 개별 칸 · <strong>6자리가 차면 자동 확인</strong> · 틀리면 칸을 비우고 빨간 글씨 &quot;인증코드가 일치하지 않아요. 다시 입력해 주세요.&quot; · [인증코드 다시 받기]</td>\n</tr>\n<tr>\n  <td>③-가 기존 회원</td>\n  <td>—</td>\n  <td>시트가 닫히고 즉시 로그인 · 토스트 &quot;로그인 완료 · 내 저금통이 열렸어요&quot; · <strong>보던 화면에 그대로 남는다</strong></td>\n</tr>\n<tr>\n  <td>③-나 신규 회원</td>\n  <td>「거의 다 됐어요」 · &quot;약관에 동의하면 가입이 끝나요.&quot;</td>\n  <td>약관 3종 + 친구 추천코드(선택) → [가입 완료] (1-3)</td>\n</tr>\n<tr>\n  <td>④ 가입 완료</td>\n  <td>「가입을 환영해요!」 · &quot;이제 포인트를 모을 수 있어요&quot;</td>\n  <td>약 1.7초 뒤 자동으로 닫히고 토스트 &quot;회원가입을 완료했어요 · 내 저금통이 열렸어요&quot;. 추천코드로 포인트를 받았으면 적립 연출을 먼저 보여준다 (참여형 4절)</td>\n</tr>\n<tr>\n  <td>⑤ 본인인증 권유 <em>(같은 날 추가 — 대화창4)</em></td>\n  <td>확인창 「본인인증을 해야 포인트 적립이 가능해요」 · &quot;지금 하지 않아도 돼요. 적립할 때 다시 안내해 드려요.&quot;</td>\n  <td>④가 닫힌 직후. <strong>[다음에 하기]</strong> → 닫고 보던 화면 그대로 · <strong>[본인인증하기]</strong> → 본인인증 시트(2-2). 인증을 마치면 적립대기를 지급하고 시트가 닫힌다 — 이어서 할 참여는 없다. <strong>띄우지 않는 경우:</strong> ①출석 카드 [로그인하고 출석하기] · 퀴즈 화면 [로그인하고 시작하기]로 가입했을 때 — 적립 버튼을 누르면 관문(2-1)에서 바로 묻기 때문(두 번 묻지 않음) ②기존 회원 로그인. 추천코드를 넣고 가입해도 <strong>문구는 같다</strong>(받을 금액을 보여주지 않음) <code>[PO 확정 2026-10-27]</code> <code>[구현]</code></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>가입·로그인 여부는 <strong>서버가 판단</strong>한다 — 이메일을 보내면 회원인지 알려 주고, 사용자는 고르지 않는다. <code>[구현]</code></li>\n<li>인증코드 유효시간 <strong>5분</strong>, 다시 받기 <strong>횟수 제한 없음</strong>. <code>[앱 정책]</code> — ⚠ 구현물은 발송·만료를 흉내만 낸다(시연용 — 아무 6자리 통과). 실제 발송·만료·시도 횟수 제한은 개발 대상</li>\n<li>시트 [✕]: ①단계면 &quot;닫을까요?&quot; · ②단계부터는 &quot;가입을 그만둘까요? — 지금 닫으면 입력한 내용이 사라지고 처음부터 다시 해야 해요.&quot; 확인창. <code>[구현]</code></li>\n<li>가입 인원 제한: 어드민 설정 <code>max_users</code>(0 = 제한 없음). 넘으면 가입 거절. <code>[구현]</code> — 시연용 장치, 상용 사용 여부 미정</li>\n</ul>"}, "s1-3": {"t": "1-3. 약관·추천코드 (신규 회원)", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>약관</td>\n  <td>[필수] 서비스 이용약관 · [필수] 개인정보 수집·이용 · [선택] 마케팅 정보 수신 — 필수 2개를 체크해야 [가입 완료]가 켜진다 <code>[구현]</code> <code>[앱 정책]</code> 1-8</td>\n</tr>\n<tr>\n  <td>약관 [보기]</td>\n  <td>지금은 토스트로 위치만 안내(시연) → 개발 시 약관 전문 화면 <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>마케팅 동의</td>\n  <td>가입 때 고른 값이 계정의 마케팅 수신 설정이 된다 <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>친구 추천코드</td>\n  <td>접힌 칸 · 넣으면 [조회]를 마쳐야 가입 — 상세는 참여형 4-2절</td>\n</tr>\n<tr>\n  <td>회원 생성 시점</td>\n  <td><strong>[가입 완료]를 누른 순간</strong> — 약관 동의 전에는 계정을 만들지 않는다 <code>[구현]</code> <code>[앱 정책]</code> 1-8</td>\n</tr>\n<tr>\n  <td>가입 실패</td>\n  <td>서버 처리 실패 → 확인창 &quot;가입하지 못했어요&quot; + [다시 시도](가입 요청을 다시 보냄). 계정은 만들어졌는데 <strong>추천코드 적용만 실패</strong>하면 [다시 시도]는 코드만 다시 적용한다 — 계정을 또 만들지 않는다 (C-LAYER R3) <code>[구현]</code></td>\n</tr>\n</tbody>\n</table>"}, "s1-4": {"t": "1-4. 세션", "h": "<ul>\n<li>로그인 유지 <strong>30일</strong> (쿠키 만료 30일). <code>[구현]</code> — 앱 정책은 앱에서 <strong>무기한</strong>(1-11). 리워드 앱 출시 때 어느 쪽으로 할지 → 미결 R-M7</li>\n<li>로그인 직후 서버에서 잔액·본인인증 여부·적립대기 여부를 다시 받는다. <code>[구현]</code></li>\n</ul>\n<hr />"}, "s1-5": {"t": "1-5. 간편 로그인 — 카카오·네이버 (v0.2 신설)", "h": "<blockquote>\n<p><strong>실제로 연동하지 않는다.</strong> 버튼이 어디에 있고 누르면 어떤 흐름으로 가는지를 보여주기 위한 <strong>시연용 흉내</strong>다. <code>[PO 확정 2026-10-27]</code></p>\n</blockquote>\n<p><strong>왜 흉내로 두는가</strong> <code>[원문]</code> <code>03_조사/09_간편가입_본인인증_타사조사_v0.1.md</code></p>\n<table>\n<thead>\n<tr>\n  <th>사업자</th>\n  <th>실연동에 필요한 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>카카오</td>\n  <td>비즈 앱 전환 → 비즈니스 정보 심사 · 개인정보 동의항목 심사 <strong>영업일 3~5일</strong>. 전화번호·CI는 별도 권한</td>\n</tr>\n<tr>\n  <td>네이버</td>\n  <td>서비스 적용에 <strong>검수 승인</strong> 필요 · <strong>CI를 주지 않는다</strong> · 휴대전화번호는 동의 시 제공</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>결정적인 것은 <strong>카카오 CI 권한 조건</strong>이다 — <em>「서비스 회원가입에 본인확인 기관에 의한 본인 인증 기능이 확인된 경우만 설정 권한 제공」</em> <code>[2차]</code>.\n즉 <strong>PASS를 먼저 갖춰야 CI를 받는 구조</strong>라, 실연동해도 <strong>중복 인증 판정에 쓸 CI는 얻지 못한다.</strong> 중복 인증·계정 통합 검증이 목적이라면 실연동의 실익이 없다.</li>\n</ul>\n<p><strong>화면</strong></p>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>가입·로그인 바텀시트에서 <strong>이메일 입력 칸 아래</strong> · 구분선 「또는」 · <strong>카카오 · 네이버</strong> 버튼 2개를 가로로</td>\n</tr>\n<tr>\n  <td>표기</td>\n  <td>버튼 아래 안내 한 줄 — <strong>「시연용이에요. 실제 카카오·네이버 로그인은 연결되어 있지 않아요.」</strong></td>\n</tr>\n<tr>\n  <td>누르면</td>\n  <td>「연결 중…」을 약 1초 보여준 뒤 <strong>그 소셜의 로그인 화면을 흉내 낸 단계</strong>가 뜬다 — <strong>이메일(아이디)을 직접 입력</strong>한다 <code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>왜 직접 넣게 하나</td>\n  <td>소셜마다 결과를 고정해 두면 시연 중에 바꿀 수 없다. <strong>입력한 이메일에 따라 갈라지게</strong> 하면 연결·통합·신규가입 <strong>세 결과를 그 자리에서 보여줄 수 있다</strong></td>\n</tr>\n<tr>\n  <td>입력 화면 안내</td>\n  <td>「시연용 화면이에요. 실제 OO 로그인 창이 아니에요.」 + <strong>어떤 주소를 넣으면 어떤 결과가 나오는지</strong> 한 줄 안내</td>\n</tr>\n<tr>\n  <td>고른 뒤</td>\n  <td>고른 소셜로 로그인한 것으로 처리하고 <strong>아래 분기</strong>를 탄다</td>\n</tr>\n</tbody>\n</table>\n<p><strong>분기 — 버튼은 하나, 결과는 두 가지</strong> <code>[앱 정책]</code> 01-3 1-6-4</p>\n<pre><code>[카카오로 시작하기] 탭\n      │\n      ▼ 「카카오 인증 중…」 (약 1초)\n      │\n      ▼ 카카오 로그인 화면(흉내) — 이메일(아이디) 입력\n      │\n      ▼ 넣은 이메일로 판단\n      ├─ 픽콕의 **다른 회원**        → 계정 통합 (3-2)  &quot;두 계정을 합칠까요?&quot;\n      ├─ **내 계정**과 같다(로그인 중) → 계정 연결 (3-1)  &quot;카카오가 연결됐어요&quot;\n      ├─ **이미 가입된 주소**(로그인 전) → 그 계정으로 **로그인 + 소셜 자동 연결**\n      └─ 픽콕에 **없다**             → 로그인 중이면 연결 · 아니면 **신규 가입**(약관 → 완료)\n</code></pre>\n<table>\n<thead>\n<tr>\n  <th>넣은 이메일</th>\n  <th>결과</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>픽콕의 다른 회원 (로그인 중)</td>\n  <td><strong>계정 통합 확인</strong>(3-2) — 합쳐질 계정·포인트 합계를 보여준다</td>\n  <td>01-3 1-6-2</td>\n</tr>\n<tr>\n  <td>내 계정과 같음 (로그인 중)</td>\n  <td><strong>계정 연결</strong>(3-1) · 토스트 「OO가 연결됐어요」</td>\n  <td>01-3 1-6-6</td>\n</tr>\n<tr>\n  <td>이미 가입된 주소 (로그인 전)</td>\n  <td><strong>그 계정으로 로그인 + 그 소셜을 로그인 수단으로 자동 연결</strong> — 합칠 상대가 없으므로 통합이 아니다</td>\n  <td><code>[PO 확정 2026-10-27]</code> · 01-3 1-4</td>\n</tr>\n<tr>\n  <td>픽콕에 없음</td>\n  <td>로그인 중 → <strong>연결</strong> / 로그인 전 → <strong>신규 가입</strong></td>\n  <td>01-3 1-6-1</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>사용자는 누르기 전에 결과를 알 수 없다. <strong>고른 뒤에 시스템이 판단해 나눈다.</strong></li>\n<li>신규 가입으로 들어와도 <strong>본인인증은 첫 적립 때</strong> 받는다(2-1). 간편 로그인이라고 달라지지 않는다.</li>\n<li><strong>판단은 서버가 한다</strong> <em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code> — 넣은 이메일을 서버가 찾는다(대표 이메일 → 없으면 통합 때 남긴 옛 이메일). 로그인 전에 가입된 주소면 <strong>서버에 로그인까지</strong> 한다(전: 화면만 로그인 → 새로고침·적립 때 「로그인이 필요해요」 · K19). 로그인 전에는 다른 회원 이메일도 「이미 가입된 주소」 줄 — 그 계정으로 로그인한다(K21). 통합은 로그인 중일 때만.</li>\n<li>시연 더미 <code>old.pickoq@naver.com</code>은 서버에 없는 통합 시연용 주소다 — 로그인 전에 넣으면 토스트 「통합 시연용 주소예요. 로그인한 뒤 계정관리 [연결]에서 넣어 주세요」 <em>(10-28 회원 묶음 — 대화창4)</em></li>\n<li>소셜로 <strong>신규 가입</strong>하면 그 소셜이 연결되고 「현재 로그인」 수단이 된다(K20) <em>(10-28 회원 묶음 — 대화창4)</em></li>\n</ul>\n<hr />"}, "s2": {"t": "2. 본인인증", "h": "<h2 id=\"s2-1\">2-1. 시점 — 첫 적립 때</h2>\n<ul>\n<li><strong>가입 때는 받지 않는다.</strong> 포인트가 처음 생기려 할 때(출석 [받기] · 퀴즈 열기 · 혜택 나가기 전 · 예약 뽑기) 받는다 — 상세 규칙·적립대기·안내 3곳은 <strong>참여형 정책서 1-6절</strong>이 기준이다.</li>\n<li>회원이 직접 할 수 있는 곳: 위 적립 순간 · <strong>가입 직후 권유 팝업(1-2 ⑤)</strong> · 홈 안내 띠 「인증하기」 · <strong>계정관리 [본인인증하기]</strong> · 포인트 내역 맨 위 [본인인증하기]. <code>[구현]</code></li>\n</ul>\n<h2 id=\"s2-2\">2-2. 화면 (본인인증 시트)</h2>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>화면 문구</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>① 통신사</td>\n  <td>「휴대폰 본인인증」 · &quot;포인트를 받으려면 본인인증이 한 번 필요해요. 통신사를 선택해 주세요.&quot;</td>\n  <td>SKT · KT · LG U+ · 알뜰폰</td>\n</tr>\n<tr>\n  <td>② 정보</td>\n  <td>「{통신사} 본인인증」 · &quot;주민등록상 정보와 같아야 해요.&quot;</td>\n  <td>이름 · 생년월일 6자리 · 휴대폰 번호(- 없이) — 셋 다 채워야 [인증번호 받기]</td>\n</tr>\n<tr>\n  <td>③ 인증번호</td>\n  <td>「인증번호 입력」 · &quot;{번호}로 문자를 보냈어요.&quot;</td>\n  <td>6자리 → [확인] · 누르면 「확인 중…」</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>②·③은 실제로는 <strong>본인확인기관이 띄우는 외부 화면</strong>이다. 픽콕은 진입 안내와 결과 처리만 만든다. <code>[분석·의견]</code> — 개발 요건은 참여형 1-6 「본인인증 개발 요건」</li>\n<li>[✕] → &quot;본인인증을 그만둘까요?&quot; 확인창. 적립 버튼에서 열었으면 &quot;지금 닫으면 이번 참여는 하지 않은 상태로 남아요.&quot; · 이어서 할 참여가 없으면(가입 직후 권유 · 홈 띠 · 계정관리 · 포인트 내역) &quot;언제든 다시 할 수 있어요. 인증 전에 받은 포인트는 적립대기로 남아요.&quot; <code>[구현]</code> <em>(같은 날 추가 — 대화창4)</em></li>\n</ul>\n<h2 id=\"s2-3\">2-3. 인증을 마치면</h2>\n<table>\n<thead>\n<tr>\n  <th>처리</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>이름</td>\n  <td>본인인증에서 받은 <strong>실명으로 바뀐다</strong> (가입 때는 이메일 앞부분) <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>휴대폰 번호</td>\n  <td>계정에 저장 · 계정관리에 「✓ 인증완료」와 함께 표시(읽기 전용) <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>적립대기</td>\n  <td>한꺼번에 지급 → 적립 연출 &quot;NP 적립! · 적립대기 포인트가 지급됐어요&quot; + 알림 「적립대기 포인트 +NP」 1건 (참여형 1-6)</td>\n</tr>\n<tr>\n  <td>적립대기가 없으면</td>\n  <td>토스트 &quot;본인인증이 완료됐어요&quot; <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>「본인인증이 완료됐어요 — 이제 포인트를 적립하고 사용할 수 있어요.」 1건 <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>이어서</td>\n  <td>하려던 참여를 그 자리에서 처리 (출석·퀴즈 등)</td>\n</tr>\n<tr>\n  <td>실패</td>\n  <td>서버 처리 실패 → 확인창 &quot;본인인증을 마치지 못했어요&quot; + [다시 시도] (C-LAYER R3)</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s2-1": {"t": "2-1. 시점 — 첫 적립 때", "h": "<ul>\n<li><strong>가입 때는 받지 않는다.</strong> 포인트가 처음 생기려 할 때(출석 [받기] · 퀴즈 열기 · 혜택 나가기 전 · 예약 뽑기) 받는다 — 상세 규칙·적립대기·안내 3곳은 <strong>참여형 정책서 1-6절</strong>이 기준이다.</li>\n<li>회원이 직접 할 수 있는 곳: 위 적립 순간 · <strong>가입 직후 권유 팝업(1-2 ⑤)</strong> · 홈 안내 띠 「인증하기」 · <strong>계정관리 [본인인증하기]</strong> · 포인트 내역 맨 위 [본인인증하기]. <code>[구현]</code></li>\n</ul>"}, "s2-2": {"t": "2-2. 화면 (본인인증 시트)", "h": "<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>화면 문구</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>① 통신사</td>\n  <td>「휴대폰 본인인증」 · &quot;포인트를 받으려면 본인인증이 한 번 필요해요. 통신사를 선택해 주세요.&quot;</td>\n  <td>SKT · KT · LG U+ · 알뜰폰</td>\n</tr>\n<tr>\n  <td>② 정보</td>\n  <td>「{통신사} 본인인증」 · &quot;주민등록상 정보와 같아야 해요.&quot;</td>\n  <td>이름 · 생년월일 6자리 · 휴대폰 번호(- 없이) — 셋 다 채워야 [인증번호 받기]</td>\n</tr>\n<tr>\n  <td>③ 인증번호</td>\n  <td>「인증번호 입력」 · &quot;{번호}로 문자를 보냈어요.&quot;</td>\n  <td>6자리 → [확인] · 누르면 「확인 중…」</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>②·③은 실제로는 <strong>본인확인기관이 띄우는 외부 화면</strong>이다. 픽콕은 진입 안내와 결과 처리만 만든다. <code>[분석·의견]</code> — 개발 요건은 참여형 1-6 「본인인증 개발 요건」</li>\n<li>[✕] → &quot;본인인증을 그만둘까요?&quot; 확인창. 적립 버튼에서 열었으면 &quot;지금 닫으면 이번 참여는 하지 않은 상태로 남아요.&quot; · 이어서 할 참여가 없으면(가입 직후 권유 · 홈 띠 · 계정관리 · 포인트 내역) &quot;언제든 다시 할 수 있어요. 인증 전에 받은 포인트는 적립대기로 남아요.&quot; <code>[구현]</code> <em>(같은 날 추가 — 대화창4)</em></li>\n</ul>"}, "s2-3": {"t": "2-3. 인증을 마치면", "h": "<table>\n<thead>\n<tr>\n  <th>처리</th>\n  <th>내용</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>이름</td>\n  <td>본인인증에서 받은 <strong>실명으로 바뀐다</strong> (가입 때는 이메일 앞부분) <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>휴대폰 번호</td>\n  <td>계정에 저장 · 계정관리에 「✓ 인증완료」와 함께 표시(읽기 전용) <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>적립대기</td>\n  <td>한꺼번에 지급 → 적립 연출 &quot;NP 적립! · 적립대기 포인트가 지급됐어요&quot; + 알림 「적립대기 포인트 +NP」 1건 (참여형 1-6)</td>\n</tr>\n<tr>\n  <td>적립대기가 없으면</td>\n  <td>토스트 &quot;본인인증이 완료됐어요&quot; <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>알림</td>\n  <td>「본인인증이 완료됐어요 — 이제 포인트를 적립하고 사용할 수 있어요.」 1건 <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>이어서</td>\n  <td>하려던 참여를 그 자리에서 처리 (출석·퀴즈 등)</td>\n</tr>\n<tr>\n  <td>실패</td>\n  <td>서버 처리 실패 → 확인창 &quot;본인인증을 마치지 못했어요&quot; + [다시 시도] (C-LAYER R3)</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s3": {"t": "3. 계정관리", "h": "<p>진입: 마이페이지 › 계정관리 (2뎁스 — 하단 탭 없음). <code>[구현]</code></p>\n<table>\n<thead>\n<tr>\n  <th>칸</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>이메일</td>\n  <td>맨 위 · 읽기 전용 · 「✓ 인증완료」 · &quot;예약 확정·안내 메일을 이 주소로 보내요&quot; · <strong>바꿀 수 없다</strong></td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-2</td>\n</tr>\n<tr>\n  <td>이름 (한글)</td>\n  <td>필수 · 20자 · 비우면 &quot;이름을 입력해 주세요&quot; · 본인인증 회원은 안내 &quot;본인인증으로 확인한 이름이에요. 표시 이름은 바꿀 수 있어요.&quot;</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>영문 이름 · 영문 성</td>\n  <td>선택 · 영문만(한글·숫자 입력 안 됨) · 30자 · 넣으면 2자 이상 — 아니면 &quot;2자 이상 입력해 주세요&quot;</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>국적</td>\n  <td>선택형 시트 — 대한민국 · 일본 · 미국 · 중국 · 대만 · 베트남 · 태국 · 싱가포르 · 호주 · 캐나다</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>전화번호</td>\n  <td>+82 · <strong>읽기 전용</strong>(본인인증 번호) · 미인증이면 &quot;본인인증 후 표시돼요&quot; + 안내 &quot;본인인증을 마치면 번호가 표시되고, 포인트를 받을 수 있어요.&quot; + <strong>[본인인증하기]</strong> · 인증 회원은 &quot;본인확인기관에서 확인한 번호예요. 바꾸려면 본인인증을 다시 해야 해요.&quot;</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>친구 추천코드</td>\n  <td>가입 후 7일 이내 · 아직 안 넣은 회원만 입력 — 참여형 4-2 · 7일 지나면 「친구추천만료」</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>[저장]</td>\n  <td><strong>바뀐 값이 있을 때만</strong> 켜진다 · 성공 &quot;저장했어요&quot;(추천코드가 적립대기로 등록되면 <strong>&quot;추천코드를 등록했어요. 본인인증하면 적립돼요&quot; 하나만</strong> — Q9 <em>(10-28 크로스체크 — 대화창4)</em>) · 칸 오류면 해당 칸 빨간 글씨 + 토스트 &quot;입력값을 확인해 주세요&quot; · 서버 실패 → 확인창 + [다시 시도]</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>[회원탈퇴]</td>\n  <td>맨 아래 글자 버튼 → 재인증(4절) → 탈퇴(5절)</td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-10 심사 요건</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>마케팅 수신 동의는 계정관리에 두지 않는다 — 앱은 설정 화면에서 바꾼다. <code>[앱 정책]</code> 1-9 (v0.9) — 리워드 설정 화면은 마이페이지 묶음에서 다룬다</li>\n<li>프로필 이미지는 공통 그림 하나 · 바꾸는 기능 없음. <code>[구현]</code></li>\n</ul>\n<hr />\n<h2 id=\"s3-1\">3-1. 계정 연결 — 로그인 수단 추가 <em>(v0.2 신설)</em></h2>\n<p><strong>정의:</strong> 지금 로그인한 계정에 <strong>로그인 수단을 하나 더 붙이는 것</strong>. 붙이려는 소셜이 <strong>아직 어느 픽콕 회원에도 없을 때</strong>다. <code>[앱 정책]</code> 01-3 1-6-1</p>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>계정관리 아래 <strong>「로그인 수단」</strong> 영역 — 카카오 · 네이버를 줄로 보여주고 각 줄에 [연결] 또는 [해제]</td>\n  <td><code>[앱 정책]</code> 1-6-5</td>\n</tr>\n<tr>\n  <td>인증</td>\n  <td><strong>재인증(4절) → 소셜 선택</strong></td>\n  <td><code>[앱 정책]</code> 1-6-6</td>\n</tr>\n<tr>\n  <td>이메일 일치</td>\n  <td><strong>상관없다</strong> — 이미 로그인한 상태에서 그 소셜을 가졌음을 보였기 때문</td>\n  <td><code>[앱 정책]</code> 1-6-6</td>\n</tr>\n<tr>\n  <td>계정 수</td>\n  <td>1개 → <strong>1개</strong> (변화 없음) · 포인트 변화 없음</td>\n  <td><code>[앱 정책]</code> 1-6-2</td>\n</tr>\n<tr>\n  <td>되돌리기</td>\n  <td><strong>[해제]로 가능</strong></td>\n  <td><code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td>지금 로그인한 수단</td>\n  <td><strong>해제할 수 없다</strong> — 버튼을 끄고 이유를 보여준다</td>\n  <td><code>[앱 정책]</code> 1-6-5</td>\n</tr>\n<tr>\n  <td>마지막 수단</td>\n  <td>이메일은 바꿀 수 없으므로(3절) 이메일이 항상 남는다 — 소셜은 전부 해제해도 된다</td>\n  <td><code>[앱 정책]</code> 1-6-5</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"s3-2\">3-2. 계정 통합 — 두 계정 합치기 <em>(v0.2 신설)</em></h2>\n<p><strong>정의:</strong> <strong>서로 다른 픽콕 회원 2개를 하나로 합치는 것</strong>. 붙이려는 소셜이 <strong>이미 다른 회원의 것일 때</strong>다. <code>[앱 정책]</code> 01-3 1-6-1</p>\n<blockquote>\n<p><strong>연결과 통합을 가르는 기준은 하나다 — 합쳐질 상대 계정이 있는가.</strong> 없으면 연결, 있으면 통합. 이미 연결된 수단이 몇 개인지와는 무관하다. <code>[앱 정책]</code> 1-6-2</p>\n</blockquote>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>대표 계정</td>\n  <td><strong>먼저 가입한 계정</strong> — 사용자에게 묻지 않는다</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td>대표 이메일</td>\n  <td>대표 계정의 이메일. 사라지는 계정 이메일은 <strong>로그인 별칭으로 안에만 남기고 화면에는 보이지 않는다</strong>(예전 이메일로 로그인해도 들어와진다)</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td>알림·인증코드</td>\n  <td><strong>대표 이메일로만</strong> 보낸다</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td><strong>포인트</strong></td>\n  <td><strong>전액 합산</strong></td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td><strong>포인트 소멸일</strong></td>\n  <td><strong>각 포인트가 쌓인 날 기준 그대로</strong> — 합쳤다고 다시 계산하지 않는다</td>\n  <td><code>[앱 정책]</code> 1-6-7 · 포인트 정책 6절</td>\n</tr>\n<tr>\n  <td><strong>적립대기 포인트</strong></td>\n  <td>양쪽의 적립대기를 그대로 가져온다. 본인인증을 마치면 <strong>합쳐진 계정에서 한꺼번에 지급</strong></td>\n  <td><code>[분석·의견]</code> — 참여형 1-6과 맞춤</td>\n</tr>\n<tr>\n  <td>계정 수</td>\n  <td>2개 → <strong>1개</strong> · 되돌릴 수 없다</td>\n  <td><code>[앱 정책]</code> 1-6-2</td>\n</tr>\n<tr>\n  <td>통합 후 세션</td>\n  <td><strong>유지</strong> — 다시 로그인하라고 하지 않는다</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n</tbody>\n</table>\n<p><strong>안전장치 — 되돌릴 수 없고 포인트가 합쳐지므로 네 가지를 둔다</strong> <code>[앱 정책]</code> 1-6-8</p>\n<table>\n<thead>\n<tr>\n  <th>#</th>\n  <th>안전장치</th>\n  <th>막는 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>1</td>\n  <td><strong>재인증 + 소셜 확인</strong>(4절)</td>\n  <td>남이 함부로 합치는 것</td>\n</tr>\n<tr>\n  <td>2</td>\n  <td><strong>합쳐질 내용을 보여주고 필수 체크</strong> — 양쪽 이메일·가입일·포인트·합계</td>\n  <td>잘못 누르는 것</td>\n</tr>\n<tr>\n  <td>3</td>\n  <td><strong>통합 이력 저장</strong> — 합친 일시·원래 계정(회원번호·이메일·가입일)·<strong>각 포인트의 원 소속</strong></td>\n  <td>되돌릴 수 없는 상태</td>\n</tr>\n<tr>\n  <td>4</td>\n  <td><strong>회원번호 매핑 저장</strong> ★</td>\n  <td><strong>적립예정 포인트가 사라지는 것</strong> (아래)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>★ 안전장치 4 — 왜 리워드에서 특히 중요한가</strong></p>\n<p>예약 적립은 <strong>체크아웃 + 7일</strong>에 확정된다(포인트 정책 3-2). 그 사이에 계정을 합치면 이런 일이 생긴다.</p>\n<pre><code>계정 B로 예약  →  트랙ID가 B의 회원번호로 나감  →  아직 적립예정\n        ↓\n   계정 통합 — B의 회원번호가 사라지고 A로 합쳐짐\n        ↓\n   며칠 뒤 리포팅 도착 — 트랙ID는 B의 회원번호\n        ↓\n   ★ 찾지 못함 → 포인트가 아무에게도 가지 않고 사라짐\n</code></pre>\n<p><strong>대응</strong> — 합칠 때 <code>B 회원번호 → A 회원번호</code> 매핑을 남기고, 리포팅을 처리할 때 <strong>회원번호를 못 찾으면 매핑을 한 번 더 본다.</strong></p>\n<blockquote>\n<p>매핑 없이 통합 기능을 열면 <strong>실제로 포인트가 사라진다.</strong> 이미 트랙ID 소실이 확인된 상태(27건 중 9건)라 통합이 새 소실 경로를 만든다. <code>[앱 정책]</code> 1-6-8</p>\n</blockquote>\n<ul>\n<li><strong>통합해도 지금 로그인한 수단은 바뀌지 않는다</strong> — 계정관리에서 통합한 소셜은 [해제]할 수 있다(K18) <em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></li>\n<li>실제 회원끼리 통합하면 상대 계정의 <strong>원장 줄과 적립대기를 그대로 옮긴다</strong>(각 적립의 소멸일 유지) → 합쳐진 계정은 삭제 · 그 계정의 세션도 끊김. 금액은 화면이 아니라 서버 값. <strong>시연 계정</strong>(탈퇴 보호와 같은 기준)은 통합 대상이 되지 않는다 — 「시연 계정끼리는 통합하지 않아요…」 <em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></li>\n</ul>\n<h2 id=\"s3-3\">3-3. 중복 본인인증 (CI) <em>(v0.2 신설)</em></h2>\n<p>같은 사람이 <strong>다른 계정에서 이미 본인인증을 마친</strong> 경우다. 본인인증은 첫 적립 때 받으므로(2-1) 이 상황은 <strong>적립하려는 순간</strong> 드러난다.</p>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>처리</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>판정</td>\n  <td>인증 결과(CI)가 <strong>이미 다른 회원에 쓰였는지</strong> 본다</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>중복이면</td>\n  <td><strong>포인트를 지급하지 않는다.</strong> 그 자리에서 <strong>&quot;이미 인증한 계정이 있어요&quot;</strong> 안내 + 상대 계정 힌트(이메일 가림 표기)</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>이어지는 길</td>\n  <td>안내에서 <strong>[두 계정 합치기]</strong> → 계정 통합(3-2)으로 잇는다</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>합치지 않으면</td>\n  <td>지금 계정은 <strong>인증되지 않은 상태로 남는다</strong> — 적립대기가 계속 쌓이고 지급되지 않는다</td>\n  <td><code>[분석·의견]</code></td>\n</tr>\n<tr>\n  <td>1인 1계정</td>\n  <td>인증을 마친 CI는 한 회원에만 붙는다</td>\n  <td><code>[앱 정책]</code> 1-6</td>\n</tr>\n<tr>\n  <td>프로토 <em>(10-28 회원 묶음 — 대화창4)</em></td>\n  <td>CI 대신 <strong>휴대폰 번호</strong>로 흉내 낸다(하이픈 무시). 다른 계정이 그 번호로 인증돼 있으면 거절 — 토스트 「이 명의로 이미 본인인증한 픽콕 계정이 있어요 (abc****@…). 그 계정으로 로그인해 주세요」 · 지금 계정은 미인증 그대로. <strong>[두 계정 합치기]는 아직 없음</strong>(E6 다음 단계)</td>\n  <td><code>[PO 결정 2026-10-28]</code> 같은 명의만 · <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>개발 대상</td>\n  <td>같은 기기 · 탈퇴 후 재가입한 사람의 추천 보상 제외(크로스체크 Q13) — 프로토에서는 흉내 내지 않는다</td>\n  <td><code>[PO 결정 2026-10-28]</code></td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"s3-4\">3-4. 통합 이력 <em>(v0.2 신설)</em></h2>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>표시</td>\n  <td><strong>계속 보여준다</strong> — 기간 제한 없음</td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n<tr>\n  <td>위치</td>\n  <td>계정관리 아래 <strong>「계정 통합 N건」</strong> 행 → 누르면 시트로 전체 이력 (최신순)</td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n<tr>\n  <td>이력 없는 회원</td>\n  <td><strong>행을 아예 보여주지 않는다</strong></td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n<tr>\n  <td>왜 계속 보여주나</td>\n  <td>합치면 <strong>대표 이메일이 바뀌므로</strong>, 「내 이메일이 왜 바뀌었지」를 확인할 단서가 화면에 남아야 한다</td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"s3-5\">3-5. 연결 해제 — 그리고 「통합 해제」는 없다 <em>(v0.2 같은 날 추가 — 대화창2)</em></h2>\n<blockquote>\n<p><strong>가장 헷갈리는 지점.</strong> 고객이 할 수 있는 것은 <strong>소셜 로그인 수단의 [해제]뿐</strong>이다. <strong>합친 계정을 다시 나누는 「통합 해제」는 없다</strong> — 고객 화면에도, 어드민에도 없다(3-2 「되돌릴 수 없다」 · 어드민 5-5). <code>[PO 확정 2026-10-27]</code></p>\n</blockquote>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>계정관리 「로그인 수단」 줄의 <strong>[해제]</strong></td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>지금 로그인한 수단</td>\n  <td>해제할 수 없다 — 누르면 토스트 「현재 로그인 중인 수단은 해제할 수 없어요」</td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-6-5</td>\n</tr>\n<tr>\n  <td>재인증</td>\n  <td><strong>받지 않는다</strong> — 되돌릴 수 있고 접근권이 줄어드는 방향이다(4절 대상 아님)</td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td>확인 화면</td>\n  <td>시트 「OO 연결을 해제할까요?」 · &quot;해제 후에는 {남는 소셜} 또는 <strong>이메일</strong>로 로그인할 수 있어요&quot; · 대표 이메일 · [취소] [해제] → 토스트 「OO 연결을 해제했어요」</td>\n  <td><code>[구현]</code> 앱 목업 M9</td>\n</tr>\n<tr>\n  <td>통합 이력이 있으면</td>\n  <td>확인 화면에 한 줄 더 — <strong>&quot;OO 로그인만 해제돼요. 통합된 계정과 포인트는 그대로예요.&quot;</strong></td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td>해제해도 그대로인 것</td>\n  <td><strong>대표 이메일 · 포인트(이관분 포함) · 통합 이력 · 통합된 상태</strong>(계정이 다시 나뉘지 않음) · <strong>옛 이메일 별칭</strong>(옛 이메일로 이메일 로그인 가능)</td>\n  <td><code>[앱 정책]</code> 1-6-12 · 3-2</td>\n</tr>\n<tr>\n  <td>빠지는 것</td>\n  <td>그 소셜로 바로 들어오는 길 하나</td>\n  <td><code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td><strong>해제한 소셜로 다시 로그인하면</strong></td>\n  <td>소셜 로그인 화면에 넣은 이메일이 <strong>대표 이메일 또는 옛 이메일 별칭</strong>이면 「이미 가입된 주소」(1-5 ③)로 보고 <strong>대표 계정으로 로그인 + 그 소셜을 다시 자동 연결</strong>한다. <strong>새 계정을 만들지 않고, 통합을 다시 묻지도 않는다</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code> — 구현은 옛 이메일을 아직 「다른 회원」으로 보고 통합 확인을 다시 띄움(프로토 수정 요청 #49)</td>\n</tr>\n<tr>\n  <td>소셜 쪽 연동 해지</td>\n  <td>실서비스는 해제할 때 소셜의 연동 해지(unlink)도 함께 부른다 — 픽콕 DB에서만 지우면 소셜의 「연결된 서비스」 목록에 남는다. 실패하면 재시도 후 안내</td>\n  <td><code>[앱 정책]</code> 1-6-12 — 시연은 흉내(1-5)라 해당 없음</td>\n</tr>\n<tr>\n  <td>저장</td>\n  <td><strong>옛 이메일 별칭은 서버가 찾는다</strong> — 통합 기록(사라진 계정 이메일 · 어드민 5-5)에 남고, 소셜 로그인 화면에 넣은 이메일을 서버가 「대표 이메일 → 옛 이메일」 순으로 찾아 대표 계정으로 로그인시킨다. <strong>연결 수단 목록은 아직 화면에서만</strong> 바뀐다(서버 저장 없음 · 새로고침하면 사라짐 · 시연 흉내). 이메일 인증코드 로그인은 아직 옛 이메일로 찾지 않는다 — 실서비스는 이메일 로그인도 옛 이메일로 찾는다</td>\n  <td><code>[구현]</code> (10-28 회원 묶음 반영)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>흐름 — [해제]를 누르면</strong></p>\n<pre><code>[해제] 누르기\n   ├─ 지금 로그인한 수단인가? ─ 예 → 토스트 「현재 로그인 중인 수단은 해제할 수 없어요」 (끝)\n   └─ 아니오\n        ▼\n   확인 시트 「OO 연결을 해제할까요?」  (재인증 없음)\n        ├─ 통합 이력이 있으면 → &quot;OO 로그인만 해제돼요. 통합된 계정과 포인트는 그대로예요.&quot;\n        ├─ [취소] → 아무것도 바뀌지 않음\n        └─ [해제] → 로그인 수단에서 OO만 빠짐\n                     대표 이메일·포인트·통합 이력·옛 이메일 별칭 = 그대로\n                     계정은 다시 나뉘지 않음\n</code></pre>\n<p><strong>흐름 — 해제한 소셜로 다시 로그인하면</strong></p>\n<pre><code>[OO로 시작하기] → OO 로그인 화면(흉내) → 이메일 입력\n   ├─ 대표 이메일 또는 옛 이메일 별칭 → 대표 계정으로 로그인 + OO 자동 재연결 (통합 다시 묻지 않음)\n   ├─ 픽콕의 다른 회원                → 계정 통합 확인 (3-2)\n   └─ 픽콕에 없음                     → 신규 가입 (1-5 ④)\n</code></pre>\n<hr />"}, "s3-1": {"t": "3-1. 계정 연결 — 로그인 수단 추가 (v0.2 신설)", "h": "<p><strong>정의:</strong> 지금 로그인한 계정에 <strong>로그인 수단을 하나 더 붙이는 것</strong>. 붙이려는 소셜이 <strong>아직 어느 픽콕 회원에도 없을 때</strong>다. <code>[앱 정책]</code> 01-3 1-6-1</p>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>계정관리 아래 <strong>「로그인 수단」</strong> 영역 — 카카오 · 네이버를 줄로 보여주고 각 줄에 [연결] 또는 [해제]</td>\n  <td><code>[앱 정책]</code> 1-6-5</td>\n</tr>\n<tr>\n  <td>인증</td>\n  <td><strong>재인증(4절) → 소셜 선택</strong></td>\n  <td><code>[앱 정책]</code> 1-6-6</td>\n</tr>\n<tr>\n  <td>이메일 일치</td>\n  <td><strong>상관없다</strong> — 이미 로그인한 상태에서 그 소셜을 가졌음을 보였기 때문</td>\n  <td><code>[앱 정책]</code> 1-6-6</td>\n</tr>\n<tr>\n  <td>계정 수</td>\n  <td>1개 → <strong>1개</strong> (변화 없음) · 포인트 변화 없음</td>\n  <td><code>[앱 정책]</code> 1-6-2</td>\n</tr>\n<tr>\n  <td>되돌리기</td>\n  <td><strong>[해제]로 가능</strong></td>\n  <td><code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td>지금 로그인한 수단</td>\n  <td><strong>해제할 수 없다</strong> — 버튼을 끄고 이유를 보여준다</td>\n  <td><code>[앱 정책]</code> 1-6-5</td>\n</tr>\n<tr>\n  <td>마지막 수단</td>\n  <td>이메일은 바꿀 수 없으므로(3절) 이메일이 항상 남는다 — 소셜은 전부 해제해도 된다</td>\n  <td><code>[앱 정책]</code> 1-6-5</td>\n</tr>\n</tbody>\n</table>"}, "s3-2": {"t": "3-2. 계정 통합 — 두 계정 합치기 (v0.2 신설)", "h": "<p><strong>정의:</strong> <strong>서로 다른 픽콕 회원 2개를 하나로 합치는 것</strong>. 붙이려는 소셜이 <strong>이미 다른 회원의 것일 때</strong>다. <code>[앱 정책]</code> 01-3 1-6-1</p>\n<blockquote>\n<p><strong>연결과 통합을 가르는 기준은 하나다 — 합쳐질 상대 계정이 있는가.</strong> 없으면 연결, 있으면 통합. 이미 연결된 수단이 몇 개인지와는 무관하다. <code>[앱 정책]</code> 1-6-2</p>\n</blockquote>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>대표 계정</td>\n  <td><strong>먼저 가입한 계정</strong> — 사용자에게 묻지 않는다</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td>대표 이메일</td>\n  <td>대표 계정의 이메일. 사라지는 계정 이메일은 <strong>로그인 별칭으로 안에만 남기고 화면에는 보이지 않는다</strong>(예전 이메일로 로그인해도 들어와진다)</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td>알림·인증코드</td>\n  <td><strong>대표 이메일로만</strong> 보낸다</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td><strong>포인트</strong></td>\n  <td><strong>전액 합산</strong></td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n<tr>\n  <td><strong>포인트 소멸일</strong></td>\n  <td><strong>각 포인트가 쌓인 날 기준 그대로</strong> — 합쳤다고 다시 계산하지 않는다</td>\n  <td><code>[앱 정책]</code> 1-6-7 · 포인트 정책 6절</td>\n</tr>\n<tr>\n  <td><strong>적립대기 포인트</strong></td>\n  <td>양쪽의 적립대기를 그대로 가져온다. 본인인증을 마치면 <strong>합쳐진 계정에서 한꺼번에 지급</strong></td>\n  <td><code>[분석·의견]</code> — 참여형 1-6과 맞춤</td>\n</tr>\n<tr>\n  <td>계정 수</td>\n  <td>2개 → <strong>1개</strong> · 되돌릴 수 없다</td>\n  <td><code>[앱 정책]</code> 1-6-2</td>\n</tr>\n<tr>\n  <td>통합 후 세션</td>\n  <td><strong>유지</strong> — 다시 로그인하라고 하지 않는다</td>\n  <td><code>[앱 정책]</code> 1-6-7</td>\n</tr>\n</tbody>\n</table>\n<p><strong>안전장치 — 되돌릴 수 없고 포인트가 합쳐지므로 네 가지를 둔다</strong> <code>[앱 정책]</code> 1-6-8</p>\n<table>\n<thead>\n<tr>\n  <th>#</th>\n  <th>안전장치</th>\n  <th>막는 것</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>1</td>\n  <td><strong>재인증 + 소셜 확인</strong>(4절)</td>\n  <td>남이 함부로 합치는 것</td>\n</tr>\n<tr>\n  <td>2</td>\n  <td><strong>합쳐질 내용을 보여주고 필수 체크</strong> — 양쪽 이메일·가입일·포인트·합계</td>\n  <td>잘못 누르는 것</td>\n</tr>\n<tr>\n  <td>3</td>\n  <td><strong>통합 이력 저장</strong> — 합친 일시·원래 계정(회원번호·이메일·가입일)·<strong>각 포인트의 원 소속</strong></td>\n  <td>되돌릴 수 없는 상태</td>\n</tr>\n<tr>\n  <td>4</td>\n  <td><strong>회원번호 매핑 저장</strong> ★</td>\n  <td><strong>적립예정 포인트가 사라지는 것</strong> (아래)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>★ 안전장치 4 — 왜 리워드에서 특히 중요한가</strong></p>\n<p>예약 적립은 <strong>체크아웃 + 7일</strong>에 확정된다(포인트 정책 3-2). 그 사이에 계정을 합치면 이런 일이 생긴다.</p>\n<pre><code>계정 B로 예약  →  트랙ID가 B의 회원번호로 나감  →  아직 적립예정\n        ↓\n   계정 통합 — B의 회원번호가 사라지고 A로 합쳐짐\n        ↓\n   며칠 뒤 리포팅 도착 — 트랙ID는 B의 회원번호\n        ↓\n   ★ 찾지 못함 → 포인트가 아무에게도 가지 않고 사라짐\n</code></pre>\n<p><strong>대응</strong> — 합칠 때 <code>B 회원번호 → A 회원번호</code> 매핑을 남기고, 리포팅을 처리할 때 <strong>회원번호를 못 찾으면 매핑을 한 번 더 본다.</strong></p>\n<blockquote>\n<p>매핑 없이 통합 기능을 열면 <strong>실제로 포인트가 사라진다.</strong> 이미 트랙ID 소실이 확인된 상태(27건 중 9건)라 통합이 새 소실 경로를 만든다. <code>[앱 정책]</code> 1-6-8</p>\n</blockquote>\n<ul>\n<li><strong>통합해도 지금 로그인한 수단은 바뀌지 않는다</strong> — 계정관리에서 통합한 소셜은 [해제]할 수 있다(K18) <em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></li>\n<li>실제 회원끼리 통합하면 상대 계정의 <strong>원장 줄과 적립대기를 그대로 옮긴다</strong>(각 적립의 소멸일 유지) → 합쳐진 계정은 삭제 · 그 계정의 세션도 끊김. 금액은 화면이 아니라 서버 값. <strong>시연 계정</strong>(탈퇴 보호와 같은 기준)은 통합 대상이 되지 않는다 — 「시연 계정끼리는 통합하지 않아요…」 <em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></li>\n</ul>"}, "s3-3": {"t": "3-3. 중복 본인인증 (CI) (v0.2 신설)", "h": "<p>같은 사람이 <strong>다른 계정에서 이미 본인인증을 마친</strong> 경우다. 본인인증은 첫 적립 때 받으므로(2-1) 이 상황은 <strong>적립하려는 순간</strong> 드러난다.</p>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>처리</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>판정</td>\n  <td>인증 결과(CI)가 <strong>이미 다른 회원에 쓰였는지</strong> 본다</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>중복이면</td>\n  <td><strong>포인트를 지급하지 않는다.</strong> 그 자리에서 <strong>&quot;이미 인증한 계정이 있어요&quot;</strong> 안내 + 상대 계정 힌트(이메일 가림 표기)</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>이어지는 길</td>\n  <td>안내에서 <strong>[두 계정 합치기]</strong> → 계정 통합(3-2)으로 잇는다</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>합치지 않으면</td>\n  <td>지금 계정은 <strong>인증되지 않은 상태로 남는다</strong> — 적립대기가 계속 쌓이고 지급되지 않는다</td>\n  <td><code>[분석·의견]</code></td>\n</tr>\n<tr>\n  <td>1인 1계정</td>\n  <td>인증을 마친 CI는 한 회원에만 붙는다</td>\n  <td><code>[앱 정책]</code> 1-6</td>\n</tr>\n<tr>\n  <td>프로토 <em>(10-28 회원 묶음 — 대화창4)</em></td>\n  <td>CI 대신 <strong>휴대폰 번호</strong>로 흉내 낸다(하이픈 무시). 다른 계정이 그 번호로 인증돼 있으면 거절 — 토스트 「이 명의로 이미 본인인증한 픽콕 계정이 있어요 (abc****@…). 그 계정으로 로그인해 주세요」 · 지금 계정은 미인증 그대로. <strong>[두 계정 합치기]는 아직 없음</strong>(E6 다음 단계)</td>\n  <td><code>[PO 결정 2026-10-28]</code> 같은 명의만 · <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>개발 대상</td>\n  <td>같은 기기 · 탈퇴 후 재가입한 사람의 추천 보상 제외(크로스체크 Q13) — 프로토에서는 흉내 내지 않는다</td>\n  <td><code>[PO 결정 2026-10-28]</code></td>\n</tr>\n</tbody>\n</table>"}, "s3-4": {"t": "3-4. 통합 이력 (v0.2 신설)", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>표시</td>\n  <td><strong>계속 보여준다</strong> — 기간 제한 없음</td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n<tr>\n  <td>위치</td>\n  <td>계정관리 아래 <strong>「계정 통합 N건」</strong> 행 → 누르면 시트로 전체 이력 (최신순)</td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n<tr>\n  <td>이력 없는 회원</td>\n  <td><strong>행을 아예 보여주지 않는다</strong></td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n<tr>\n  <td>왜 계속 보여주나</td>\n  <td>합치면 <strong>대표 이메일이 바뀌므로</strong>, 「내 이메일이 왜 바뀌었지」를 확인할 단서가 화면에 남아야 한다</td>\n  <td><code>[앱 정책]</code> 1-6-7-1</td>\n</tr>\n</tbody>\n</table>"}, "s3-5": {"t": "3-5. 연결 해제 — 그리고 「통합 해제」는 없다 (v0.2 같은 날 추가 — 대화창2)", "h": "<blockquote>\n<p><strong>가장 헷갈리는 지점.</strong> 고객이 할 수 있는 것은 <strong>소셜 로그인 수단의 [해제]뿐</strong>이다. <strong>합친 계정을 다시 나누는 「통합 해제」는 없다</strong> — 고객 화면에도, 어드민에도 없다(3-2 「되돌릴 수 없다」 · 어드민 5-5). <code>[PO 확정 2026-10-27]</code></p>\n</blockquote>\n<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>계정관리 「로그인 수단」 줄의 <strong>[해제]</strong></td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>지금 로그인한 수단</td>\n  <td>해제할 수 없다 — 누르면 토스트 「현재 로그인 중인 수단은 해제할 수 없어요」</td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-6-5</td>\n</tr>\n<tr>\n  <td>재인증</td>\n  <td><strong>받지 않는다</strong> — 되돌릴 수 있고 접근권이 줄어드는 방향이다(4절 대상 아님)</td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td>확인 화면</td>\n  <td>시트 「OO 연결을 해제할까요?」 · &quot;해제 후에는 {남는 소셜} 또는 <strong>이메일</strong>로 로그인할 수 있어요&quot; · 대표 이메일 · [취소] [해제] → 토스트 「OO 연결을 해제했어요」</td>\n  <td><code>[구현]</code> 앱 목업 M9</td>\n</tr>\n<tr>\n  <td>통합 이력이 있으면</td>\n  <td>확인 화면에 한 줄 더 — <strong>&quot;OO 로그인만 해제돼요. 통합된 계정과 포인트는 그대로예요.&quot;</strong></td>\n  <td><code>[구현]</code> <code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td>해제해도 그대로인 것</td>\n  <td><strong>대표 이메일 · 포인트(이관분 포함) · 통합 이력 · 통합된 상태</strong>(계정이 다시 나뉘지 않음) · <strong>옛 이메일 별칭</strong>(옛 이메일로 이메일 로그인 가능)</td>\n  <td><code>[앱 정책]</code> 1-6-12 · 3-2</td>\n</tr>\n<tr>\n  <td>빠지는 것</td>\n  <td>그 소셜로 바로 들어오는 길 하나</td>\n  <td><code>[앱 정책]</code> 1-6-12</td>\n</tr>\n<tr>\n  <td><strong>해제한 소셜로 다시 로그인하면</strong></td>\n  <td>소셜 로그인 화면에 넣은 이메일이 <strong>대표 이메일 또는 옛 이메일 별칭</strong>이면 「이미 가입된 주소」(1-5 ③)로 보고 <strong>대표 계정으로 로그인 + 그 소셜을 다시 자동 연결</strong>한다. <strong>새 계정을 만들지 않고, 통합을 다시 묻지도 않는다</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code> — 구현은 옛 이메일을 아직 「다른 회원」으로 보고 통합 확인을 다시 띄움(프로토 수정 요청 #49)</td>\n</tr>\n<tr>\n  <td>소셜 쪽 연동 해지</td>\n  <td>실서비스는 해제할 때 소셜의 연동 해지(unlink)도 함께 부른다 — 픽콕 DB에서만 지우면 소셜의 「연결된 서비스」 목록에 남는다. 실패하면 재시도 후 안내</td>\n  <td><code>[앱 정책]</code> 1-6-12 — 시연은 흉내(1-5)라 해당 없음</td>\n</tr>\n<tr>\n  <td>저장</td>\n  <td><strong>옛 이메일 별칭은 서버가 찾는다</strong> — 통합 기록(사라진 계정 이메일 · 어드민 5-5)에 남고, 소셜 로그인 화면에 넣은 이메일을 서버가 「대표 이메일 → 옛 이메일」 순으로 찾아 대표 계정으로 로그인시킨다. <strong>연결 수단 목록은 아직 화면에서만</strong> 바뀐다(서버 저장 없음 · 새로고침하면 사라짐 · 시연 흉내). 이메일 인증코드 로그인은 아직 옛 이메일로 찾지 않는다 — 실서비스는 이메일 로그인도 옛 이메일로 찾는다</td>\n  <td><code>[구현]</code> (10-28 회원 묶음 반영)</td>\n</tr>\n</tbody>\n</table>\n<p><strong>흐름 — [해제]를 누르면</strong></p>\n<pre><code>[해제] 누르기\n   ├─ 지금 로그인한 수단인가? ─ 예 → 토스트 「현재 로그인 중인 수단은 해제할 수 없어요」 (끝)\n   └─ 아니오\n        ▼\n   확인 시트 「OO 연결을 해제할까요?」  (재인증 없음)\n        ├─ 통합 이력이 있으면 → &quot;OO 로그인만 해제돼요. 통합된 계정과 포인트는 그대로예요.&quot;\n        ├─ [취소] → 아무것도 바뀌지 않음\n        └─ [해제] → 로그인 수단에서 OO만 빠짐\n                     대표 이메일·포인트·통합 이력·옛 이메일 별칭 = 그대로\n                     계정은 다시 나뉘지 않음\n</code></pre>\n<p><strong>흐름 — 해제한 소셜로 다시 로그인하면</strong></p>\n<pre><code>[OO로 시작하기] → OO 로그인 화면(흉내) → 이메일 입력\n   ├─ 대표 이메일 또는 옛 이메일 별칭 → 대표 계정으로 로그인 + OO 자동 재연결 (통합 다시 묻지 않음)\n   ├─ 픽콕의 다른 회원                → 계정 통합 확인 (3-2)\n   └─ 픽콕에 없음                     → 신규 가입 (1-5 ④)\n</code></pre>\n<hr />"}, "s4": {"t": "4. 재인증", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>대상</td>\n  <td><strong>회원탈퇴 · 계정 연결(3-1) · 계정 통합(3-2)</strong></td>\n  <td><code>[앱 정책]</code> 1-7</td>\n</tr>\n<tr>\n  <td>이유</td>\n  <td>로그인을 오래 유지하므로, 남이 기기를 쓰는 경우를 막기 위해 되돌릴 수 없는 작업 전에 한 번 더 확인</td>\n  <td><code>[앱 정책]</code> 1-7</td>\n</tr>\n<tr>\n  <td>방식</td>\n  <td><strong>지금 로그인한 수단으로 1회</strong> — 이메일 회원은 이메일 인증코드</td>\n  <td><code>[앱 정책]</code> 1-7</td>\n</tr>\n<tr>\n  <td>화면</td>\n  <td>「본인 확인이 필요해요」 · &quot;회원탈퇴는 되돌리기 어려워서 지금 로그인한 수단으로 한 번 더 확인해요.&quot; · [이메일로 인증코드 받기] → 「인증코드를 입력해 주세요」 6자리 → [확인]</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>틀리면</td>\n  <td>토스트 &quot;인증코드가 일치하지 않아요&quot;</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>연결일 때 문구</td>\n  <td>연결은 [해제]로 되돌릴 수 있어 &quot;되돌리기 어려워서&quot; 대신 <strong>&quot;다른 사람이 내 계정에 로그인 수단을 붙이지 못하게 지금 로그인한 수단으로 한 번 더 확인해요.&quot;</strong> (#51)</td>\n  <td><em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>소셜로 로그인한 회원</td>\n  <td>버튼 <strong>「OO로 다시 인증하기」</strong> → 「OO 인증 중…」 → 통과(그 소셜 로그인을 다시 하는 흉내 · K22)</td>\n  <td><em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>코드 확인</td>\n  <td><strong>서버가 확인</strong>한다 — 로그인한 회원 이메일로 보낸 것으로 표시(전: 고정 이메일 · 화면 안 확인 #36). 시연용 — 아무 6자리 통과</td>\n  <td><em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>닫기</td>\n  <td>단계형 시트라 <strong>배경을 눌러도 닫히지 않는다</strong> — [✕]만(K27 · C-LAYER L-SHEET-STEP). 탈퇴 시트도 같다</td>\n  <td><em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></td>\n</tr>\n<tr>\n  <td>연결의 다음</td>\n  <td>재인증을 마치면 <strong>소셜 로그인 화면(이메일 입력)</strong> — 넣은 이메일로 연결/통합이 갈린다(전: 바로 연결 · K17)</td>\n  <td><em>(10-28 회원 묶음 — 대화창4)</em> <code>[구현]</code></td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s5": {"t": "5. 회원탈퇴", "h": "<h2 id=\"s5-1\">5-1. 흐름</h2>\n<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>화면</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>① 재인증</td>\n  <td>4절</td>\n  <td>—</td>\n</tr>\n<tr>\n  <td>② 확인</td>\n  <td>「정말 탈퇴하시겠어요?」 · 경고 상자 &quot;아래 포인트가 모두 사라져요&quot; — 적립 완료 NP · <strong>적립대기 NP</strong> · 합계</td>\n  <td>안내 4줄: 되돌릴 수 없음 · 적립대기 포인트는 지급되지 않음 · <strong>같은 이메일은 탈퇴일 +7일이 지나야 다시 가입</strong> · 연결된 로그인 수단은 자동 해제 · [필수] &quot;위 내용을 확인했습니다&quot; 체크 → [다음]</td>\n</tr>\n<tr>\n  <td>③ 사유</td>\n  <td>「떠나시는 이유를 알려주세요」</td>\n  <td>6개 중 <strong>1개 이상 복수 선택</strong> 필수 — 자주 이용하지 않아요 · 원하는 숙소나 가격을 찾기 어려워요 · 다른 서비스가 더 저렴하거나 편리해요 · 개인정보 보호가 걱정돼요 · 앱/서비스 사용이 불편해요 · 기타(직접 입력, 200자) → [탈퇴하기] · [이전]</td>\n</tr>\n<tr>\n  <td>④ 완료</td>\n  <td>「탈퇴가 완료됐어요」 · &quot;그동안 이용해 주셔서 고마웠어요.&quot; · 안내: 모든 기기에서 로그아웃 · 같은 이메일은 7일 뒤부터 다시 가입</td>\n  <td>[확인] → 로그아웃 상태로 홈 · 토스트 &quot;탈퇴가 완료됐어요&quot; · 완료 화면은 [✕]·배경으로 닫히지 않음</td>\n</tr>\n</tbody>\n</table>\n<p>근거: <code>[구현]</code> 화면·문구 · <code>[앱 정책]</code> 1-10 (앱 안에서 탈퇴 완결 — App Store 5.1.1(v))</p>\n<h2 id=\"s5-2\">5-2. 탈퇴할 때 처리 (서버)</h2>\n<table>\n<thead>\n<tr>\n  <th>처리</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>보유 포인트</td>\n  <td><strong>전부 소멸</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code> <code>[앱 정책]</code> 1-10</td>\n</tr>\n<tr>\n  <td>적립대기 포인트</td>\n  <td><strong>전부 소멸</strong> — 본인인증 전이라 지급되지 않은 예약 적립·친구 추천·관리자 지급분 포함</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>진행 중인 출금·픽샵</td>\n  <td>미정 — 신청 중인 현금 전환·사용 전 쿠폰 처리</td>\n  <td>미결 R-M6</td>\n</tr>\n<tr>\n  <td>재가입 제한</td>\n  <td><strong>탈퇴일 + 7일(7일째 자정까지)</strong> 같은 이메일로 가입 불가. 시도하면 안내 문구로 거절(문구는 개발 시 확정)</td>\n  <td><code>[PO 확정 2026-10-27]</code> <code>[구현]</code> 화면 문구</td>\n</tr>\n<tr>\n  <td>제한을 위한 보관</td>\n  <td>7일간 판단할 수 있도록 <strong>탈퇴 이메일(또는 그 해시값)과 탈퇴일만</strong> 보관 후 삭제</td>\n  <td><code>[분석·의견]</code> — 법무 확인 필요(R-M6)</td>\n</tr>\n<tr>\n  <td>계정 데이터</td>\n  <td>즉시 삭제 — 어드민 회원 목록에 탈퇴 회원을 남기지 않는다</td>\n  <td><code>[구현]</code> 어드민 안내</td>\n</tr>\n<tr>\n  <td>친구 추천 관계</td>\n  <td>이미 지급된 건은 회수하지 않음 · 그 추천코드는 사용 불가</td>\n  <td>참여형 4-5 E6·E7</td>\n</tr>\n<tr>\n  <td>세션</td>\n  <td>모든 기기에서 로그아웃</td>\n  <td><code>[구현]</code> 문구</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>구현</strong> <em>(10-28 회원 묶음 — 대화창4)</em> — 서버가 처리한다: 보유 포인트·적립대기·계정 데이터 삭제(원장·예약·출금·픽샵 주문·알림 포함) · 세션 전부 끊기 · 탈퇴 이메일과 탈퇴일만 보관 · 7일 재가입 거절. 확인 화면 금액 = 서버의 보유·적립대기(표기 「적립대기」).<ul>\n<li><strong>시연 계정 보호</strong> <code>[PO 결정 2026-10-28]</code> — 이 기능을 넣을 때 이미 있던 회원(설정 <code>demo_protect_max_id</code> 이하)은 탈퇴해도 데이터를 지우지 않고 <strong>로그아웃만</strong> 한다. 토스트 「탈퇴가 완료됐어요 · 시연 계정이라 데이터는 남겨 뒀어요」. 이후 새로 가입한 계정은 실제로 지워진다.</li>\n<li>진행 중인 출금·픽샵(미결 R-M6)은 프로토에서 <strong>함께 지운다</strong> — 정책 확정 전의 시연 처리.</li>\n</ul>\n</li>\n</ul>\n<hr />"}, "s5-1": {"t": "5-1. 흐름", "h": "<table>\n<thead>\n<tr>\n  <th>단계</th>\n  <th>화면</th>\n  <th>규칙</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>① 재인증</td>\n  <td>4절</td>\n  <td>—</td>\n</tr>\n<tr>\n  <td>② 확인</td>\n  <td>「정말 탈퇴하시겠어요?」 · 경고 상자 &quot;아래 포인트가 모두 사라져요&quot; — 적립 완료 NP · <strong>적립대기 NP</strong> · 합계</td>\n  <td>안내 4줄: 되돌릴 수 없음 · 적립대기 포인트는 지급되지 않음 · <strong>같은 이메일은 탈퇴일 +7일이 지나야 다시 가입</strong> · 연결된 로그인 수단은 자동 해제 · [필수] &quot;위 내용을 확인했습니다&quot; 체크 → [다음]</td>\n</tr>\n<tr>\n  <td>③ 사유</td>\n  <td>「떠나시는 이유를 알려주세요」</td>\n  <td>6개 중 <strong>1개 이상 복수 선택</strong> 필수 — 자주 이용하지 않아요 · 원하는 숙소나 가격을 찾기 어려워요 · 다른 서비스가 더 저렴하거나 편리해요 · 개인정보 보호가 걱정돼요 · 앱/서비스 사용이 불편해요 · 기타(직접 입력, 200자) → [탈퇴하기] · [이전]</td>\n</tr>\n<tr>\n  <td>④ 완료</td>\n  <td>「탈퇴가 완료됐어요」 · &quot;그동안 이용해 주셔서 고마웠어요.&quot; · 안내: 모든 기기에서 로그아웃 · 같은 이메일은 7일 뒤부터 다시 가입</td>\n  <td>[확인] → 로그아웃 상태로 홈 · 토스트 &quot;탈퇴가 완료됐어요&quot; · 완료 화면은 [✕]·배경으로 닫히지 않음</td>\n</tr>\n</tbody>\n</table>\n<p>근거: <code>[구현]</code> 화면·문구 · <code>[앱 정책]</code> 1-10 (앱 안에서 탈퇴 완결 — App Store 5.1.1(v))</p>"}, "s5-2": {"t": "5-2. 탈퇴할 때 처리 (서버)", "h": "<table>\n<thead>\n<tr>\n  <th>처리</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>보유 포인트</td>\n  <td><strong>전부 소멸</strong></td>\n  <td><code>[PO 확정 2026-10-27]</code> <code>[앱 정책]</code> 1-10</td>\n</tr>\n<tr>\n  <td>적립대기 포인트</td>\n  <td><strong>전부 소멸</strong> — 본인인증 전이라 지급되지 않은 예약 적립·친구 추천·관리자 지급분 포함</td>\n  <td><code>[PO 확정 2026-10-27]</code></td>\n</tr>\n<tr>\n  <td>진행 중인 출금·픽샵</td>\n  <td>미정 — 신청 중인 현금 전환·사용 전 쿠폰 처리</td>\n  <td>미결 R-M6</td>\n</tr>\n<tr>\n  <td>재가입 제한</td>\n  <td><strong>탈퇴일 + 7일(7일째 자정까지)</strong> 같은 이메일로 가입 불가. 시도하면 안내 문구로 거절(문구는 개발 시 확정)</td>\n  <td><code>[PO 확정 2026-10-27]</code> <code>[구현]</code> 화면 문구</td>\n</tr>\n<tr>\n  <td>제한을 위한 보관</td>\n  <td>7일간 판단할 수 있도록 <strong>탈퇴 이메일(또는 그 해시값)과 탈퇴일만</strong> 보관 후 삭제</td>\n  <td><code>[분석·의견]</code> — 법무 확인 필요(R-M6)</td>\n</tr>\n<tr>\n  <td>계정 데이터</td>\n  <td>즉시 삭제 — 어드민 회원 목록에 탈퇴 회원을 남기지 않는다</td>\n  <td><code>[구현]</code> 어드민 안내</td>\n</tr>\n<tr>\n  <td>친구 추천 관계</td>\n  <td>이미 지급된 건은 회수하지 않음 · 그 추천코드는 사용 불가</td>\n  <td>참여형 4-5 E6·E7</td>\n</tr>\n<tr>\n  <td>세션</td>\n  <td>모든 기기에서 로그아웃</td>\n  <td><code>[구현]</code> 문구</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>구현</strong> <em>(10-28 회원 묶음 — 대화창4)</em> — 서버가 처리한다: 보유 포인트·적립대기·계정 데이터 삭제(원장·예약·출금·픽샵 주문·알림 포함) · 세션 전부 끊기 · 탈퇴 이메일과 탈퇴일만 보관 · 7일 재가입 거절. 확인 화면 금액 = 서버의 보유·적립대기(표기 「적립대기」).<ul>\n<li><strong>시연 계정 보호</strong> <code>[PO 결정 2026-10-28]</code> — 이 기능을 넣을 때 이미 있던 회원(설정 <code>demo_protect_max_id</code> 이하)은 탈퇴해도 데이터를 지우지 않고 <strong>로그아웃만</strong> 한다. 토스트 「탈퇴가 완료됐어요 · 시연 계정이라 데이터는 남겨 뒀어요」. 이후 새로 가입한 계정은 실제로 지워진다.</li>\n<li>진행 중인 출금·픽샵(미결 R-M6)은 프로토에서 <strong>함께 지운다</strong> — 정책 확정 전의 시연 처리.</li>\n</ul>\n</li>\n</ul>\n<hr />"}, "s6": {"t": "6. 로그아웃", "h": "<table>\n<thead>\n<tr>\n  <th>항목</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>위치</td>\n  <td>마이페이지 맨 아래 [로그아웃] (로그인 상태에서만)</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>확인</td>\n  <td><strong>확인창 없이 바로</strong> — 다시 로그인하면 되므로</td>\n  <td><code>[PO 확정 2026-10-26]</code> C-LAYER R5</td>\n</tr>\n<tr>\n  <td>이후</td>\n  <td>토스트 &quot;로그아웃했어요&quot; · 마이페이지(비로그인 상태)에 남는다</td>\n  <td><code>[구현]</code> — 웹 Phase1은 메인 이동(8-8). 구현 기준을 따른다</td>\n</tr>\n<tr>\n  <td>서버</td>\n  <td>세션을 끊는다</td>\n  <td><code>[구현]</code> 서버 세션 삭제(#34 반영) <em>(10-28 회원 묶음 — 대화창4)</em> 표기 정정</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s7": {"t": "7. 어드민 — 회원", "h": "<p>상세 규칙은 <code>리워드_어드민_정책서_v0.2.md</code> 5절. 여기에는 회원 정책과 맞물리는 것만 둔다.</p>\n<table>\n<thead>\n<tr>\n  <th>화면</th>\n  <th>규칙</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>회원 목록</td>\n  <td>열: 선택 · 회원ID(이메일) · 이름 · 본인인증(인증완료/미인증) · 추천코드 · 추천한 친구 · 보유 포인트 · 가입일 · [상세] · 찾기: 이메일·이름·추천코드 · 가입일 기간 · 본인인증(전체/완료/미완료)</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>보유 포인트 표시</td>\n  <td>미인증인데 (원장 + 적립대기) ≥ 1이면 금액 옆에 작은 「적립대기」</td>\n  <td><code>[구현]</code> 어드민 5-1</td>\n</tr>\n<tr>\n  <td>회원 상세</td>\n  <td>왼쪽 = 추천코드·포인트 요약·기본 정보·본인인증·출금 계좌·포인트 수동 처리 / 오른쪽 = 포인트 내역</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>미인증 회원 상세</td>\n  <td>「사용 가능」 대신 「보유 NP 적립대기」 + 노란 안내 &quot;본인인증 전이에요. 아래 포인트는 고객 화면에 보이지 않고, 본인인증을 하면 그때 지급돼요.&quot; + 내역 칩(예약·친구 추천·관리자 지급·회수·이전에 쌓인 포인트)</td>\n  <td><code>[구현]</code> 어드민 5-2</td>\n</tr>\n<tr>\n  <td>포인트 수동 지급·회수</td>\n  <td>단건(상세) · 일괄(목록 선택) · 사유 필수 · 미인증 회원은 적립대기로 · 알림 없음</td>\n  <td><code>[구현]</code> 참여형 1-6 · 어드민 5-3</td>\n</tr>\n<tr>\n  <td>본인인증 처리</td>\n  <td>관리자가 「인증 완료」로 바꾸면 적립대기 지급 · 관리자 로그</td>\n  <td><code>[구현]</code> 서버만 있음 — ⚠ <strong>어드민 화면에 버튼이 없다</strong> → 프로토 수정 요청 #35</td>\n</tr>\n<tr>\n  <td>탈퇴 회원</td>\n  <td>목록에 남기지 않음 (5-2)</td>\n  <td><code>[구현]</code></td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s8": {"t": "8. 예외", "h": "<table>\n<thead>\n<tr>\n  <th>#</th>\n  <th>상황</th>\n  <th>처리</th>\n  <th>근거</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>E1</td>\n  <td>인증코드 6자리가 아님</td>\n  <td>&quot;인증번호 6자리를 입력해 주세요&quot;</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>E2</td>\n  <td>인증코드 불일치</td>\n  <td>칸 비움 + &quot;인증코드가 일치하지 않아요. 다시 입력해 주세요.&quot;</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>E3</td>\n  <td>이미 가입된 이메일로 가입 요청</td>\n  <td>&quot;이미 가입된 이메일이에요&quot; (정상 흐름에서는 ②에서 기존 회원으로 분기되므로 생기지 않음)</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>E4</td>\n  <td>탈퇴 후 7일 안에 같은 이메일로 가입</td>\n  <td>가입 거절 + 다시 가입할 수 있는 날짜 안내 — 「탈퇴한 이메일은 M월 D일부터 다시 가입할 수 있어요」</td>\n  <td><code>[PO 확정]</code> · <code>[구현]</code> <em>(10-28 회원 묶음 — 대화창4)</em></td>\n</tr>\n<tr>\n  <td>E5</td>\n  <td>가입 도중 시트를 닫음</td>\n  <td>확인창 → 닫으면 계정을 만들지 않음(약관 동의 전)</td>\n  <td><code>[구현]</code></td>\n</tr>\n<tr>\n  <td>E6</td>\n  <td>본인인증 정보가 이미 다른 계정에 쓰임(중복 CI)</td>\n  <td><strong>다음 단계</strong> — 계정 통합 흐름으로 잇는다(방향만 PO 확정). 그 전까지는 지급하지 않고 기존 계정 안내</td>\n  <td><code>[PO 확정 2026-10-27]</code> R-M2</td>\n</tr>\n<tr>\n  <td>E7</td>\n  <td>만 14세 미만</td>\n  <td>미정</td>\n  <td>R-M3</td>\n</tr>\n<tr>\n  <td>E8</td>\n  <td>외국인(국내 휴대폰 없음)</td>\n  <td>미정 — 본인인증을 못 하면 적립을 받을 수 없음</td>\n  <td>R-M4</td>\n</tr>\n<tr>\n  <td>E9</td>\n  <td>정지 회원</td>\n  <td>미정 — 로그인·적립 차단 범위와 안내 화면</td>\n  <td>R-M5</td>\n</tr>\n</tbody>\n</table>\n<hr />"}, "s9": {"t": "9. 미결", "h": "<table>\n<thead>\n<tr>\n  <th>#</th>\n  <th>항목</th>\n  <th>현재</th>\n  <th>다음</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><del>R-M1</del></td>\n  <td><del>카카오·네이버 간편 가입</del></td>\n  <td><strong>해소 2026-10-27</strong> → <strong>1-5절</strong>(시연용 흉내로 확정)</td>\n  <td>—</td>\n</tr>\n<tr>\n  <td><del>R-M2</del></td>\n  <td><del>계정 연결·통합 · 중복 본인인증</del></td>\n  <td><strong>해소 2026-10-27</strong> → <strong>3-1 · 3-2 · 3-3 · 3-4절</strong></td>\n  <td>—</td>\n</tr>\n<tr>\n  <td>R-M8</td>\n  <td><strong>회원번호 매핑</strong> (3-2 안전장치 4)</td>\n  <td>정책만 정함</td>\n  <td>리포팅 처리에서 매핑을 보는 구현 · 보관 기간. <strong>없으면 통합 시 적립예정 포인트가 사라진다</strong></td>\n</tr>\n<tr>\n  <td>R-M9</td>\n  <td>간편 로그인 실연동</td>\n  <td><strong>흉내만</strong>(1-5)</td>\n  <td>실제로 붙일 시점·주체 — 카카오 비즈 앱 심사·네이버 검수 · <strong>CI는 PASS가 먼저</strong></td>\n</tr>\n<tr>\n  <td>R-M10</td>\n  <td>통합 시 적립대기</td>\n  <td>「합쳐서 가져온다」만 정함(3-2)</td>\n  <td>양쪽 적립대기가 <strong>추천 월 상한</strong>에 걸릴 때의 처리(참여형 4-4)</td>\n</tr>\n<tr>\n  <td>R-M3</td>\n  <td>만 14세 미만</td>\n  <td>정책 없음</td>\n  <td>본인인증 생년월일로 판별 가능 — 차단/법정대리인 동의 결정</td>\n</tr>\n<tr>\n  <td>R-M4</td>\n  <td>외국인</td>\n  <td>정책 없음</td>\n  <td>국내 휴대폰 없는 회원의 적립 가능 여부</td>\n</tr>\n<tr>\n  <td>R-M5</td>\n  <td>정지 회원</td>\n  <td>정책 없음 (참여형 2-8 E8도 미결)</td>\n  <td>정지 사유·범위·안내 화면</td>\n</tr>\n<tr>\n  <td>R-M6</td>\n  <td>탈퇴 데이터</td>\n  <td>즉시 삭제 원칙만</td>\n  <td>재가입 7일 판단용 보관 항목·기간(법무) · 진행 중인 출금·쿠폰 처리</td>\n</tr>\n<tr>\n  <td>R-M7</td>\n  <td>로그인 유지 기간</td>\n  <td>구현 30일</td>\n  <td>앱 출시 시 무기한(앱 정책 1-11) 여부</td>\n</tr>\n</tbody>\n</table>"}}};
